@Component("quarantine-subscriber")
public class QuarantineSubscriber extends BaseSubscriber {

	public QuarantineSubscriber() {
	}
	
    public SubscriptionQueryResult<List<Quarantine>, Quarantine> quarantineSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllQuarantineQuery(), 
                		ResponseTypes.multipleInstancesOf(Quarantine.class),
                		ResponseTypes.instanceOf(Quarantine.class));
    }

    public SubscriptionQueryResult<Quarantine, Quarantine> quarantineSubscribe(@DestinationVariable UUID quarantineId) {
        return queryGateway
                .subscriptionQuery(new FindQuarantineQuery(new LoadQuarantineFilter(quarantineId)), 
                		ResponseTypes.instanceOf(Quarantine.class),
                		ResponseTypes.instanceOf(Quarantine.class));
    }





}

